task.code-example:

function validateDomain(domain: string, existingDomains: string[]): string | null {
  // Check for duplicates
  if (existingDomains.includes(domain)) {
    return 'Domain already in whitelist';
  }

  // Validate format
  const domainRegex = /^(\*\.)?[a-zA-Z0-9]([a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(\.[a-zA-Z0-9]([a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)*$/;
  const localhostRegex = /^(localhost|127\.0\.0\.1)$/;

  if (!domainRegex.test(domain) && !localhostRegex.test(domain)) {
    return 'Invalid domain format';
  }

  return null; // Valid
}


def matches_whitelist(origin: str, allowed_domains: List[str]) -> bool:
    """
    Check if origin matches any allowed domain.
    Supports wildcards: *.example.com matches api.example.com
    """
    from urllib.parse import urlparse

    parsed = urlparse(origin)
    domain = parsed.netloc.lower()

    for allowed in allowed_domains:
        if allowed.startswith('*.'):
            # Wildcard matching
            base = allowed[2:].lower()
            if domain.endswith('.' + base) or domain == base:
                return True
        else:
            # Exact matching
            if domain == allowed.lower():
                return True

    return False


// Handle mobile keyboard
if (window.visualViewport) {
  window.visualViewport.addEventListener('resize', () => {
    const viewport = window.visualViewport;
    const keyboardHeight = window.innerHeight - viewport.height;

    if (keyboardHeight > 0) {
      // Keyboard is visible - adjust chat window
      chatContainer.style.marginBottom = `${keyboardHeight}px`;
    } else {
      // Keyboard hidden - reset
      chatContainer.style.marginBottom = '0';
    }
  });
}

